import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root object (the adapter will position/rotate/scale it)
  const root = new Group();

  // Plane geometry – size will be driven by texture aspect ratio later if needed
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously; function stays synchronous
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Preserve base position for hover animation
  const baseY = mesh.position.y;
  let hoverTl = null;
  let clickTl = null;

  function handleHover(isHover) {
    // Expect a boolean; true = enter, false = leave
    if (hoverTl) hoverTl.kill();

    hoverTl = gsap.timeline({ onComplete: () => (hoverTl = null) });
    const targetY = isHover ? baseY + 0.15 : baseY;
    const duration = isHover ? 0.7 : 0.3;
    const ease = isHover ? 'power3.out' : 'power3.in';

    hoverTl.to(mesh.position, { y: targetY, duration, ease });
  }

  function handleClick() {
    if (clickTl) clickTl.kill();

    clickTl = gsap.timeline({ onComplete: () => (clickTl = null) });
    clickTl
      .to(
        mesh.scale,
        { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' }
      )
      .to(
        mesh.scale,
        { x: 1, y: 1, z: 1, duration: 0.2, ease: 'power2.out' },
        '+=0.05'
      )
      .add(() => {
        ctx.emit('hub-collection.select');
      });
  }

  // Attach handlers for the runtime to call
  root.userData.handlers = {
    hover: handleHover,
    click: handleClick,
  };

  // Cleanup resources and kill timelines
  root.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (clickTl) clickTl.kill();
    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();
  };

  return root;
}
